-- Lee 2026-11-06: 화면 글(description)에서만 뺌 — 원문 전체는 source_text에 그대로(R5 회사명 근거·CLAUDE.md ④). 내가 원문 글 뒤에 붙인 '포스터 옮김' 부분(근무시간·급여 중복 원인)만 뺌(#5437 선례). 입구 ingest_job job_id+update_fields.
select public.ingest_job($ingest${"title": "nhẹ cafe Bách Nghệ Kinh Bắc tuyển nhân viên pha chế & phục vụ – part-time 23.000đ/giờ, full-time 26.000đ/giờ", "company": "nhẹ cafe – Bách Nghệ Kinh Bắc", "category": "am_thuc_do_uong", "occupation_code": "5132", "occupation_evidence": "Nhân viên Pha chế & Phục vụ", "salary": "23.000 – 26.000đ/giờ", "salary_min": 23000, "salary_max": 26000, "salary_period": "hour", "hours": "Part-time: 7h – 13h / 13h – 18h / 18h – 23h; Full-time: 7h – 15h / 15h – 23h", "location": "128 Đ. Triệu Việt Vương, P. Võ Cường, Bắc Ninh", "employer_phone": "0389922734", "num_hires": 3, "work_period": "Full-time, Part-time", "description": "[source:facebook] 📢 128 Đ. Triệu Việt Vương, P, Võ Cường, Bắc Ninh\nChúng mình đang tìm thêm người vào team\nBạn thích không khí quán cafe, thích pha chế và thích trò chuyện với khách? Vậy thì mình hợp nhau rồi đó.\n👉Vị trí: Nhân viên Pha chế & Phục vụ\n👉Cần tuyển 3 part tối\n- Tối: 18h - 23h\n💰Quyền lợi:\n- Part-time: 23.000đ/giờ, thu nhập khoảng 3 - 3,5 triệu/tháng\n- Full-time: 26.000đ/giờ, thu nhập khoảng 7 - 9 triệu/tháng, phụ cấp ăn 30.000đ/ca\nMôi trường trẻ trung, năng động\nYêu cầu nho nhỏ: gắn bó lâu dài sẽ được ưu tiên.\nLiên hệ: 038.9922.734\n📲 038.9922.734", "source_text": "📢 128 Đ. Triệu Việt Vương, P, Võ Cường, Bắc Ninh\nChúng mình đang tìm thêm người vào team\nBạn thích không khí quán cafe, thích pha chế và thích trò chuyện với khách? Vậy thì mình hợp nhau rồi đó.\n👉Vị trí: Nhân viên Pha chế & Phục vụ\n👉Cần tuyển 3 part tối\n- Tối: 18h - 23h\n💰Quyền lợi:\n- Part-time: 23.000đ/giờ, thu nhập khoảng 3 - 3,5 triệu/tháng\n- Full-time: 26.000đ/giờ, thu nhập khoảng 7 - 9 triệu/tháng, phụ cấp ăn 30.000đ/ca\nMôi trường trẻ trung, năng động\nYêu cầu nho nhỏ: gắn bó lâu dài sẽ được ưu tiên.\nLiên hệ: 038.9922.734\n📲 038.9922.734", "images": ["fb/nhe-cafe-20261106.png"], "job_id": 5507, "update_fields": ["description"], "channel": "sql_file"}$ingest$::jsonb) as job_id \gset
select step, outcome from public.job_ingest_log where raw_id = (select max(id) from public.job_ingest_raw where job_id = :job_id) order by array_position(array['preserve','dedup','occupation','location','publication'], step);
